    37	export function getDeviceLabelTime(date: Date): LabelTime {
    38	  return {
    39	    labelDate: `${date.getFullYear()}-${padTimePart(date.getMonth() + 1)}-${padTimePart(date.getDate())}`,
    40	    labelTime: `${padTimePart(date.getHours())}:${padTimePart(date.getMinutes())}`,
    41	  };
