    44	function labelTimeToMinute(labelTime: string): number | undefined {
    45	  const match = LABEL_TIME_PATTERN.exec(labelTime);
    46	  if (!match) {
    47	    return undefined;
    48	  }
    49	
    50	  return Number(match[1]) * 60 + Number(match[2]);
    51	}
